def f(g,bg,kind):
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]; out=g[:]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                adj=False
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            if 0<=a+dx<h and 0<=b+dy<w and not seen[a+dx][b+dy] and g[a+dx][b+dy]==bg:
                                if kind=='ortho' and (dx or dy)==0: adj=True
                                seen[a+dx][b+dy]=True; st.append((a+dx,b+dy))
                # check adjacency via neighbors of members
                ok=all(not any(0<=a+dx<h and 0<=b+dy<w and g[a+dx][b+dy]==0
                         for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]) for a,b in comp)
                if ok and len(comp)>=2:
                    for a,b in comp: out[a][b]=bg
    return out
